  "strategy": "Simple synchronous counter with direct control",
  "description": "The design uses a single 8-bit register driven by clock edges and control signals, eliminating combinational loops. It saturates at the bounds and resets asynchronously for predictable initial state. The architecture avoids extra pipeline stages to keep logic minimal.",
  "blocks": [
    {
      "name": "CounterCtrl",
      "desc": "Handles enable and reset to drive the count register on clock edges."
    },
    {
      "name": "CountReg",
      "desc": "Stores the current count value and updates it synchronously based on enable and reset."
    }
  ],
  "mermaid": "graph TD\n  In[\"clk\"] --> Ctrl[CounterCtrl]\n  Ctrl --> Reg[CountReg]\n  Reg --> Out[count]"
}
